import sys


def calc(expr: str) -> int | str:
    if hasattr(sys, "set_int_max_str_digits"):
        sys.set_int_max_str_digits(0)

    # Tokenize: integer literals become int, everything else is a 1-char str.
    tokens = []
    i, n = 0, len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif "0" <= c <= "9":
            j = i
            while j < n and "0" <= expr[j] <= "9":
                j += 1
            tokens.append(int(expr[i:j]))
            i = j
        else:
            tokens.append(c)
            i += 1
    tokens.append(None)  # end-of-input sentinel
    pos = 0

    def peek():
        return tokens[pos]

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def trunc_div(a, b):
        if b == 0:
            raise ValueError
        q = abs(a) // abs(b)
        return q if (a < 0) == (b < 0) else -q

    def trunc_mod(a, b):
        return a - b * trunc_div(a, b)

    def parse_primary():
        tok = advance()
        if isinstance(tok, int):
            return tok
        # tok == "("
        value = parse_expr()
        advance()  # consume ")"
        return value

    def parse_power():
        # Flat right-associative chain v0 ^ v1 ^ ... ; each operand after a ^
        # may carry leading unary minuses, which apply to the whole remaining power.
        vals = [parse_primary()]
        neg = []
        while peek() == "^":
            advance()
            flips = 0
            while peek() == "-":
                advance()
                flips ^= 1
            neg.append(flips)
            vals.append(parse_primary())
        result = vals[-1]
        for k in range(len(vals) - 2, -1, -1):
            exp = -result if neg[k] else result
            if exp < 0:
                raise ValueError
            result = vals[k] ** exp
        return result

    def parse_unary():
        neg = False
        while peek() == "-":
            advance()
            neg = not neg
        value = parse_power()
        return -value if neg else value

    def parse_term():
        value = parse_unary()
        while peek() in ("*", "/", "%"):
            op = advance()
            rhs = parse_unary()
            if op == "*":
                value = value * rhs
            elif op == "/":
                value = trunc_div(value, rhs)
            else:
                value = trunc_mod(value, rhs)
        return value

    def parse_expr():
        value = parse_term()
        while peek() in ("+", "-"):
            op = advance()
            rhs = parse_term()
            value = value + rhs if op == "+" else value - rhs
        return value

    try:
        return parse_expr()
    except ValueError:
        return "error"
